/// @title Callback for IUnitFlowV3PoolActions#flash
/// @notice Any contract that calls IUnitFlowV3PoolActions#flash must implement this interface
interface IUnitFlowV3FlashCallback {
    /// @notice Called to `msg.sender` after transferring to the recipient from IUnitFlowV3Pool#flash.
    /// @dev In the implementation you must repay the pool the tokens sent by flash plus the computed fee amounts.
    /// The caller of this method must be checked to be a UnitFlowV3Pool deployed by the canonical UnitFlowV3Factory.
    /// @param fee0 The fee amount in token0 due to the pool by the end of the flash
    /// @param fee1 The fee amount in token1 due to the pool by the end of the flash
    /// @param data Any data passed through by the caller via the IUnitFlowV3PoolActions#flash call
    function unitFlowV3FlashCallback(
        uint256 fee0,
        uint256 fee1,
        bytes calldata data
    ) external;
}

// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Callback for IUnitFlowV3PoolActions#mint
/// @notice Any contract that calls IUnitFlowV3PoolActions#mint must implement this interface
interface IUnitFlowV3MintCallback {
    /// @notice Called to `msg.sender` after minting liquidity to a position from IUnitFlowV3Pool#mint.
    /// @dev In the implementation you must pay the pool tokens owed for the minted liquidity.
    /// The caller of this method must be checked to be a UnitFlowV3Pool deployed by the canonical UnitFlowV3Factory.
    /// @param amount0Owed The amount of token0 due to the pool for the minted liquidity
    /// @param amount1Owed The amount of token1 due to the pool for the minted liquidity
    /// @param data Any data passed through by the caller via the IUnitFlowV3PoolActions#mint call
    function unitFlowV3MintCallback(
        uint256 amount0Owed,
        uint256 amount1Owed,
        bytes calldata data
    ) external;
}

// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Callback for IUnitFlowV3PoolActions#swap
/// @notice Any contract that calls IUnitFlowV3PoolActions#swap must implement this interface
interface IUnitFlowV3SwapCallback {
    /// @notice Called to `msg.sender` after executing a swap via IUnitFlowV3Pool#swap.
    /// @dev In the implementation you must pay the pool tokens owed for the swap.
    /// The caller of this method must be checked to be a UnitFlowV3Pool deployed by the canonical UnitFlowV3Factory.
    /// amount0Delta and amount1Delta can both be 0 if no tokens were swapped.
    /// @param amount0Delta The amount of token0 that was sent (negative) or must be received (positive) by the pool by
    /// the end of the swap. If positive, the callback must send that amount of token0 to the pool.
    /// @param amount1Delta The amount of token1 that was sent (negative) or must be received (positive) by the pool by
    /// the end of the swap. If positive, the callback must send that amount of token1 to the pool.
    /// @param data Any data passed through by the caller via the IUnitFlowV3PoolActions#swap call
    function unitFlowV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

